void findPath(int r, int c, vector<vector<int>>& maze, string& path,
vector<string>& res) {
int n = maze.size();
// If destination is reached, store the path
if (r == n - 1 && c == n - 1) {
res.push_back(path);
return;
}
// Mark current cell as visited
maze[r][c] = 0;
for (int i = 0; i < 4; i++) {
